import React from 'react';
import { Building } from '../../types/game';
import Button from '../ui/Button';
import '../../styles/components/BuildingInfo.css';

interface BuildingInfoProps {
  building: Building;
  onClose: () => void;
  onBuild?: (buildingId: string) => Promise<void>; // Actualizado para manejar async
  canBuild?: boolean;
  showBuildOptions?: boolean;
  playerResources?: { gold: number; wood: number; stone: number };
}

const BuildingInfo: React.FC<BuildingInfoProps> = ({
  building,
  onClose,
  onBuild,
  canBuild,
  showBuildOptions,
  playerResources
}) => {
  const canAfford = playerResources && Object.entries(building.cost).every(
    ([resource, amount]) => playerResources[resource as keyof typeof playerResources] >= amount
  );

  const showBuildButton = showBuildOptions && !building.built && 
    (building.is_castle || building.requirements?.every(req => 
      // Verificar si los requisitos están construidos
      building.requirements?.includes(req)
    ));

  return (
    <div className="building-info-panel">
      <div className="building-info-header">
        <h3>{building.name}</h3>
        <button onClick={onClose}>×</button>
      </div>

      <div className="building-info-content">
        <div className="building-status">
          <p>Estado: {building.built ? 'Construido' : 'Sin construir'}</p>
          {building.is_castle && <p>Edificio principal de la ciudad</p>}
          {building.can_recruit && <p>Permite reclutar unidades</p>}
        </div>

        {!building.built && (
          <div className="building-cost">
            <h4>Coste de construcción:</h4>
            {Object.entries(building.cost).map(([resource, amount]) => (
              <div key={resource} className="resource-cost">
                <span>{resource}: {amount}</span>
                {playerResources && (
                  <span className={playerResources[resource as keyof typeof playerResources] >= amount ? 'sufficient' : 'insufficient'}>
                    (Tienes: {playerResources[resource as keyof typeof playerResources]})
                  </span>
                )}
              </div>
            ))}
          </div>
        )}

        {showBuildButton && (
          <Button
            onClick={() => onBuild?.(building.id)}
            disabled={!canBuild || !canAfford}
            className="build-button"
          >
            Construir
          </Button>
        )}

        {building.built && building.can_recruit && building.available_creatures.length > 0 && (
          <div className="available-units">
            <h4>Unidades disponibles:</h4>
            <ul>
              {building.available_creatures.map(creature => (
                <li key={creature.type}>{creature.type}: {creature.count} disponibles</li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default BuildingInfo;
